/* order_service.h - one function per use case, opaque context */
struct order_service;
struct order_service *order_service_new(const struct ports *p);
int order_service_place(struct order_service *svc,
                        const struct place_order_cmd *cmd, struct order_id *out);

/* order_service.c */
int order_service_place(struct order_service *svc, const struct place_order_cmd *cmd,
                        struct order_id *out) {
    struct transaction *tx = NULL;
    if (svc->ports->begin(svc->ports->ctx, &tx) != 0) return ERR_TX;
    if (svc->ports->place(svc->ports->ctx, tx, cmd, out) != 0) {
        svc->ports->rollback(svc->ports->ctx, tx);
        return ERR_DOMAIN;
    }
    if (svc->ports->commit(svc->ports->ctx, tx) != 0) {
        svc->ports->rollback(svc->ports->ctx, tx);
        return ERR_TX;
    }
    return 0;                                      /* one transaction per use case */
}
